CREATE TRIGGER RefCusConditionLanguage_Combined
	ON RefCusConditionLanguage
	FOR INSERT, UPDATE, DELETE
	AS
	IF (SELECT CASE WHEN EXISTS(SELECT 1 FROM INSERTED) AND NOT EXISTS(SELECT 1 FROM DELETED) THEN 1 ELSE 0 end) = 1
	BEGIN
		UPDATE t SET
		ZXJ_DataSetPK = ZX1_DataSetPK,
		ZXJ_DataSetCode = ZX1_DataSetCode
		FROM RefCusConditionLanguage t
		JOIN inserted ON t.ZXJ_PK = inserted.ZXJ_PK
		LEFT JOIN RefCusCondition ON inserted.ZXJ_ZX1_Condition = ZX1_PK
	END

	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT t.ZXJ_DataSetPK, t.ZXJ_DataSetCode
	FROM RefCusConditionLanguage t
	JOIN inserted ON t.ZXJ_PK = inserted.ZXJ_PK
	UNION
	SELECT ZXJ_DataSetPK, ZXJ_DataSetCode
	FROM deleted

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN @sourcePK ON RVC_ParentPK = PK AND RVC_ParentCode = TablePrefix
	WHERE RVC_IsPublished = 1

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO

CREATE TRIGGER RefCusConditionLanguage_DataProcessingResult_Delete
	ON RefCusConditionLanguage
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.ZXJ_PK
	END
GO
